        uint256 liquidityFee = 7;
        uint256 buybackFee = 7;
        uint256 reflectionFee = 6;
        uint256 marketingFee = 6;
        uint256 feeDenominator = 100;

        console.log("Setting fees to: Liq=%s%%, Buy=%s%%, Ref=%s%%, Mar=%s%% (Denominator=%s)",
